#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<string> names(n);
    unordered_map<string, int> index;

    for (int i = 0; i < n; i++) {
        cin >> names[i];
        index[names[i]] = i;
    }

    vector<vector<int>> graph(n);
    vector<int> indegree(n, 0);

    for (int i = 0; i < m; i++) {
        string a, b;
        cin >> a >> b;

        int from = index[a];
        int to = index[b];

        graph[from].push_back(to);
        indegree[from]++;
    }

    queue<int> ready;

    for (int i = 0; i < n; i++) {
        if (indegree[i] == 0)
            ready.push(i);
    }

    vector<int> order;

    while (!ready.empty()) {
        int current = ready.front();
        ready.pop();

        order.push_back(current);

        for (int next : graph[current]) {
            indegree[next]--;

            if (indegree[next] == 0)
                ready.push(next);
        }
    }

    if ((int)order.size() != n) {
        cout << "CYCLE\n";
        return 0;
    }

    for (int i = 0; i < n; i++) {
        if (i) cout << " ";
        cout << names[order[i]];
    }

    cout << "\n";
}

